import dev.kelmagic.client.face.EyeTravel;import org.joml.Vector3f;
public class TravelTest {public static void main(String[] a){int n=0;for(float y=-3;y<=3;y+=.01f){var iris=new Vector3f(.1f,1.7f,-.234567f);var pupil=new Vector3f(.12f,1.72f,-.234567f);float z=iris.z;var delta=new Vector3f(pupil).sub(iris);EyeTravel.translate(iris,.25f,y);EyeTravel.translate(pupil,.25f,y);if(Float.floatToIntBits(z)!=Float.floatToIntBits(iris.z)||Float.floatToIntBits(z)!=Float.floatToIntBits(pupil.z))throw new AssertionError("depth");if(new Vector3f(pupil).sub(iris).distance(delta)>1e-6)throw new AssertionError("relative pupil seat");if(Math.abs(iris.y-(1.7f+Math.clamp(y,-1.15f,1.15f)/16))>1e-6)throw new AssertionError("vertical");n++;}if(EyeTravel.vertical(Float.NaN)!=0)throw new AssertionError();System.out.println("PASS "+n+" vertical inputs: explicit +/-1.15 bounds, shared iris/pupil XY displacement, bit-identical Z, finite fallback.");}}
